import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { raster } from "./tokens.stylex";
import { rs } from "./rs";

const styles = stylex.create({
  card: {
    borderWidth: 0,
    borderStyle: "none",
    borderRadius: 0,
    padding: 0,
    maxWidth: 360,
    backgroundColor: "transparent",
    boxShadow: "none",
  },
  inner: {
    boxSizing: "border-box",
    borderWidth: 0,
    borderRadius: 0,
    minHeight: 0,
    padding: 0,
    backgroundColor: "transparent",
  },
  label: {
    fontSize: 12,
    fontWeight: 600,
    color: raster.ink,
    letterSpacing: "-0.01em",
    display: "block",
    marginBottom: 6,
  },
  title: {
    fontSize: 17,
    fontWeight: 600,
    color: raster.ink,
    letterSpacing: "-0.02em",
    marginTop: 0,
    marginBottom: 8,
  },
  body: {
    fontSize: 14,
    color: raster.gray,
    fontWeight: 500,
    letterSpacing: "-0.01em",
    lineHeight: 1.6,
    margin: 0,
  },
});

export const Card = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  function Card({ className, style, ...props }, ref) {
    const sx = rs(["rs-card", className], styles.card);
    return <div ref={ref} {...props} className={sx.className} style={{ ...sx.style, ...style }} />;
  },
);

export function CardInner({ className, style, ...props }: React.HTMLAttributes<HTMLDivElement>) {
  const sx = rs(["rs-card-in", className], styles.inner);
  return <div {...props} className={sx.className} style={{ ...sx.style, ...style }} />;
}

export function CardLabel({ className, style, ...props }: React.HTMLAttributes<HTMLSpanElement>) {
  const sx = rs(["rs-card-label", className], styles.label);
  return <span {...props} className={sx.className} style={{ ...sx.style, ...style }} />;
}

export function CardTitle({ className, style, ...props }: React.HTMLAttributes<HTMLHeadingElement>) {
  const sx = rs(["rs-card-title", className], styles.title);
  return <h3 {...props} className={sx.className} style={{ ...sx.style, ...style }} />;
}

export function CardBody({ className, style, ...props }: React.HTMLAttributes<HTMLParagraphElement>) {
  const sx = rs(["rs-card-body", className], styles.body);
  return <p {...props} className={sx.className} style={{ ...sx.style, ...style }} />;
}

import type { CSSProperties } from "react";
import * as stylex from "@stylexjs/stylex";
import { cx } from "./cx";

type StyleXProps = { className?: string; style?: CSSProperties };

/** Merge Raster class names with StyleX props. CSS-first classes stay on the node. */
export function rs(classNames: Array<string | false | null | undefined>, ...styles: unknown[]): StyleXProps {
  const sx = (stylex.props as (...args: unknown[]) => StyleXProps)(...styles);
  return {
    className: cx(...classNames, sx.className),
    style: sx.style,
  };
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Card: typography stack. No outline. Chrome-square. ── */
.rs-card{
  --rs-out:0;
  --rs-gap:20px;
  --rs-in:max(0px,calc(var(--rs-out) - var(--rs-gap)));
  border:0;
  border-radius:var(--rs-out);
  padding:0;
  max-width:360px;
  background:none;
  box-shadow:none
}
.rs-card-label{font-size:12px;font-weight:600;color:var(--accent);letter-spacing:-.01em;display:block;margin-bottom:6px}
.rs-card-title{font-size:17px;font-weight:600;color:var(--text);letter-spacing:-.02em;margin:0 0 8px}
.rs-card-body{font-size:14px;color:var(--text-secondary);font-weight:500;letter-spacing:-.01em;line-height:1.6;margin:0}
.rs-card-in{
  box-sizing:border-box;
  border:0;
  border-radius:var(--rs-in);
  min-height:0;
  padding:0;
  background:none
}
.rs-card .rs-btn-primary,.rs-card .rs-btn-ghost,.rs-card .rs-input,.rs-card .rs-textarea{border-radius:var(--rs-in)}
.rs-card .rs-btn-group{--rs-out:var(--rs-in);border-radius:var(--rs-out)}
